impl Document {
    pub(crate) fn compare_abstract_event(
        &self,
        other: &Document,
        a: &AbstractEvent,
        b: &AbstractEvent,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        if a.get_activation_reason_representation_ref()
            != b.get_activation_reason_representation_ref()
        {
            return Err(format!(
                "{path}: ACTIVATION_REASON_REPRESENTATION_REF mismatch"
            ));
        }
        Ok(())
    }

    pub(crate) fn compare_exclusive_area(
        &self,
        other: &Document,
        a: &ExclusiveArea,
        b: &ExclusiveArea,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        Ok(())
    }

    pub(crate) fn compare_exclusive_area_nesting_order(
        &self,
        other: &Document,
        a: &ExclusiveAreaNestingOrder,
        b: &ExclusiveAreaNestingOrder,
        path: &str,
    ) -> Result<(), String> {
        self.compare_referrable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        let list_a = a.get_exclusive_area_refs();
        let list_b = b.get_exclusive_area_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: EXCLUSIVE_AREA_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.EXCLUSIVE_AREA_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.EXCLUSIVE_AREA_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(other, x, y, &format!("{path}.EXCLUSIVE_AREA_REFS[{index}]"))?;
        }
        Ok(())
    }

    pub(crate) fn compare_executable_entity(
        &self,
        other: &Document,
        a: &ExecutableEntity,
        b: &ExecutableEntity,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        let list_a = a.get_activation_reasons();
        let list_b = b.get_activation_reasons();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: ACTIVATION_REASONS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .executable_entity_activation_reasons
                .get(*x)
                .ok_or_else(|| {
                    format!("{path}.ACTIVATION_REASONS[{index}]: id not found in own arena")
                })?;
            let y = other
                .executable_entity_activation_reasons
                .get(*y)
                .ok_or_else(|| {
                    format!("{path}.ACTIVATION_REASONS[{index}]: id not found in other arena")
                })?;
            self.compare_executable_entity_activation_reason(
                other,
                x,
                y,
                &format!("{path}.ACTIVATION_REASONS[{index}]"),
            )?;
        }
        let list_a = a.get_can_enter_refs();
        let list_b = b.get_can_enter_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CAN_ENTER_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.CAN_ENTER_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.CAN_ENTER_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(other, x, y, &format!("{path}.CAN_ENTER_REFS[{index}]"))?;
        }
        let list_a = a.get_exclusive_area_nesting_order_refs();
        let list_b = b.get_exclusive_area_nesting_order_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: EXCLUSIVE_AREA_NESTING_ORDER_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!(
                    "{path}.EXCLUSIVE_AREA_NESTING_ORDER_REFS[{index}]: id not found in own arena"
                )
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| format!("{path}.EXCLUSIVE_AREA_NESTING_ORDER_REFS[{index}]: id not found in other arena"))?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.EXCLUSIVE_AREA_NESTING_ORDER_REFS[{index}]"),
            )?;
        }
        if a.get_minimum_start_interval() != b.get_minimum_start_interval() {
            return Err(format!("{path}: MINIMUM_START_INTERVAL mismatch"));
        }
        if a.get_reentrancy_level() != b.get_reentrancy_level() {
            return Err(format!("{path}: REENTRANCY_LEVEL mismatch"));
        }
        let list_a = a.get_runs_inside_refs();
        let list_b = b.get_runs_inside_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: RUNS_INSIDE_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.RUNS_INSIDE_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.RUNS_INSIDE_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(other, x, y, &format!("{path}.RUNS_INSIDE_REFS[{index}]"))?;
        }
        if a.get_sw_addr_method_ref() != b.get_sw_addr_method_ref() {
            return Err(format!("{path}: SW_ADDR_METHOD_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_executable_entity_activation_reason(
        &self,
        other: &Document,
        a: &ExecutableEntityActivationReason,
        b: &ExecutableEntityActivationReason,
        path: &str,
    ) -> Result<(), String> {
        self.compare_implementation_props(other, a.base(), b.base(), path)?;
        if a.get_bit_position() != b.get_bit_position() {
            return Err(format!("{path}: BIT_POSITION mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_internal_behavior(
        &self,
        other: &Document,
        a: &InternalBehavior,
        b: &InternalBehavior,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_structure_element(other, a.base(), b.base(), path)?;
        let list_a = a.get_constant_memories();
        let list_b = b.get_constant_memories();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CONSTANT_MEMORIES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.parameter_data_prototypes.get(*x).ok_or_else(|| {
                format!("{path}.CONSTANT_MEMORIES[{index}]: id not found in own arena")
            })?;
            let y = other.parameter_data_prototypes.get(*y).ok_or_else(|| {
                format!("{path}.CONSTANT_MEMORIES[{index}]: id not found in other arena")
            })?;
            self.compare_parameter_data_prototype(
                other,
                x,
                y,
                &format!("{path}.CONSTANT_MEMORIES[{index}]"),
            )?;
        }
        let list_a = a.get_constant_value_mapping_refs();
        let list_b = b.get_constant_value_mapping_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: CONSTANT_VALUE_MAPPING_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.CONSTANT_VALUE_MAPPING_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.CONSTANT_VALUE_MAPPING_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.CONSTANT_VALUE_MAPPING_REFS[{index}]"),
            )?;
        }
        let list_a = a.get_data_type_mapping_refs();
        let list_b = b.get_data_type_mapping_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: DATA_TYPE_MAPPING_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.DATA_TYPE_MAPPING_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.DATA_TYPE_MAPPING_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.DATA_TYPE_MAPPING_REFS[{index}]"),
            )?;
        }
        let list_a = a.get_exclusive_areas();
        let list_b = b.get_exclusive_areas();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: EXCLUSIVE_AREAS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.exclusive_areas.get(*x).ok_or_else(|| {
                format!("{path}.EXCLUSIVE_AREAS[{index}]: id not found in own arena")
            })?;
            let y = other.exclusive_areas.get(*y).ok_or_else(|| {
                format!("{path}.EXCLUSIVE_AREAS[{index}]: id not found in other arena")
            })?;
            self.compare_exclusive_area(other, x, y, &format!("{path}.EXCLUSIVE_AREAS[{index}]"))?;
        }
        let list_a = a.get_exclusive_area_nesting_orders();
        let list_b = b.get_exclusive_area_nesting_orders();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: EXCLUSIVE_AREA_NESTING_ORDERS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.exclusive_area_nesting_orders.get(*x).ok_or_else(|| {
                format!("{path}.EXCLUSIVE_AREA_NESTING_ORDERS[{index}]: id not found in own arena")
            })?;
            let y = other.exclusive_area_nesting_orders.get(*y).ok_or_else(|| {
                format!(
                    "{path}.EXCLUSIVE_AREA_NESTING_ORDERS[{index}]: id not found in other arena"
                )
            })?;
            self.compare_exclusive_area_nesting_order(
                other,
                x,
                y,
                &format!("{path}.EXCLUSIVE_AREA_NESTING_ORDERS[{index}]"),
            )?;
        }
        let list_a = a.get_static_memories();
        let list_b = b.get_static_memories();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: STATIC_MEMORIES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.variable_data_prototypes.get(*x).ok_or_else(|| {
                format!("{path}.STATIC_MEMORIES[{index}]: id not found in own arena")
            })?;
            let y = other.variable_data_prototypes.get(*y).ok_or_else(|| {
                format!("{path}.STATIC_MEMORIES[{index}]: id not found in other arena")
            })?;
            self.compare_variable_data_prototype(
                other,
                x,
                y,
                &format!("{path}.STATIC_MEMORIES[{index}]"),
            )?;
        }
        Ok(())
    }
}
